  PanelText_UI_Events_Panel_Arachne_StageGroup_Text_C_Introduction_Content = {
    Text = "Les lumières s'embrasent. Les applaudissements s'éteignent. Le public attend avec impatience.\nIl est temps de monter sur scène, mes chers enfants. Allez — jouez, déchirez vos âmes et vendez vos secrets les plus profonds. Prenez vos blessures les plus dévastatrices et façonnez-les en douceurs pour le plaisir du public. Baignez-vous avidement dans ce seul rayon de lumière allumé rien que pour vous, jusqu'à ce que le rideau tombe pour ensevelir aussi bien vous que votre public.\n\nVoici la scène à laquelle vous étiez destinés — montez ! N'ayez pas peur ; nul besoin de trac."
  },
