  PanelText_UI_Events_Panel_Caraboo_StageGroup_Text_C_Introduction_Content = {
    Text = "♪~~♫~~♪~~♫~~♪~~♫~~\nSous la montagne de neige, chaque guide s'en souvient, et chaque enfant la chante encore. Elle est la volonté de la montagne majestueuse faite chair, elle est la déesse miséricordieuse Umapati. Son pouvoir divin est dispersé à travers le monde des mortels ; ses trésors sont introuvables. Ils sont si proches qu'on pourrait les toucher ; ils ne laissent aucune trace. \nAbandonner quelque chose. S'accrocher à quelque chose. Quiconque a le cœur faux envers la véritable forme de la déesse sera enseveli dans la montagne de neige pour toujours, aux côtés de la montagne qui est morte."
  },
