    Text = "Nouvelle Lune et Neige Profonde"
  },
  PanelText_UI_Events_Panel_Castor_StageGroup_Text_C_Introduction_Content = {
    Text = "La vie d'un oiseau est destinée à être une vie de liberté. Tu devrais voir le moment où il brise sa coquille, il reprend la liberté de vivre des mains de la mort. Tu devrais voir le moment où il apprend à voler, il reprend la liberté de vivre seul en s'échappant de son nid douillet. Si maintenant, tu devais jeter la clé de la liberté dans l'abîme de la mort, alors il n'hésiterait pas à sauter, choisissant de faire face à la tempête de la mort entre une vie étroite et une liberté infinie."
  },
