  PanelText_UI_Events_Panel_Clementine_StageGroup_Text_C_Introduction_Content = {
    Text = "Depuis ce moment, elle n'a plus versé la moindre larme. \n Errant seule, elle dérive dans un monde peuplé d'étrangers. \n Un grand plan va bientôt commencer, constituant son ultime adieu. \n Elle est la psychologue la plus accomplie, c'est là sa thérapie la plus accomplie."
