  PanelText_UI_Events_Panel_Daffodil_StageGroup_Text_C_Introduction_Content = {
    Text = "Dans cette petite ville côtière, il y a une rue commerçante animée. Le commerce maritime a attiré ici d'innombrables produits modernes, et tant que vous payez suffisamment en Léofang, vous pourrez toujours trouver des articles satisfaisants. \n Sauf pour une petite boutique au coin de la rue, qui est remplie d'antiques mystérieux. Dans la fumée émise par une pipe, la propriétaire, portant un chapeau à larges bords, vous dévoilera lentement un sourire. \n « Bienvenue à la boutique de soulagement, ici, tous vos besoins peuvent être satisfaits, tant que vous payez une rémunération adéquate... » \n « Bien sûr, bien sûr, les prix sont justes, et il n'y a pas de tromperie. »"
