  PanelText_UI_Events_Panel_KathiguRa_StageGroup_Text_C_Introduction_Content = {
    Text = "Elle se dresse à nouveau sur la Terre, la vengeance qui réduit tout en cendres arrive comme convenu.\n\nC'est une chasse sans fin, c'est le feu brûlant du Maître des Flammes Explosives.\n\nElle parcourra chaque recoin, tuant tous ceux qui ont signé un pacte avec la mort.\n\nFuis, fuis, échappe-toi dans les ténèbres les plus profondes, va dans cet endroit où tu crois ne pas être trouvé.\n\nBien que cela soit futile, car Il foulera chaque monde.\n\nIl chassera tout jusqu'à ce que tout soit réduit en cendres."
  },
