  PanelText_UI_Events_Panel_Mouchette_StageGroup_Text_C_Introduction_Content = {
    Text = "Un jour, tu réalises soudainement que tu es devenu différent. \n Personne ne le remarque car tu exhibes toujours les mêmes comportements et as la même belle apparence. \n Mais tu sais très bien que le cœur rouge autrefois brillant est maintenant couvert par un masque fait de brume. \n \"Si je peux continuer à faire semblant, suis-je toujours le même moi qu'avant ?\" \n Heureusement, cette question ne reste pas dans ton esprit plus d'une seconde ; après tout, avant que le masque ne soit levé, personne ne connaît tes véritables pensées. \n \"Alors, mettons-nous en route~\""
  },
