    Text = "Elle regardait la grande porte au bout du monde et franchit le seuil sans hésiter. \n Cliquetis, elle tourna la poignée, impatiente de voir ce qu'il y avait derrière la porte. \n Cependant, il n'y avait rien derrière, elle glissa et tomba dans le vide. \n Elle aurait dû le savoir, un cadeau qui arrive trop directement a toujours un prix élevé."
