  PanelText_UI_Events_Panel_Pickman_StageGroup_Text_C_Introduction_Content = {
    Text = "Entre la raison et l'effondrement, un rouleau de peinture trompeur se déploie lentement. \n Les illusions que tu méprises dessinent des couleurs éclatantes, \n la perte de contrôle que tu crains forme une loyauté. \n Ici, la folie est l'instinct de l'art, la source du monde, \n c'est la seule vérité qui ne mentira pas."
