    Text = "Ces haine et amour, ces tendresses et blessures, ce que nous avons eu et ce que nous avons manqué, sont déjà entremêlés et indissociables. \n Laissons donc notre sang et notre chair couler ensemble, ils se rassembleront en un seul endroit, formant notre destin indivisible."
