    Text = "Quand la sinistre lumière blanche transperce à nouveau les fenêtres de la Haute Maison, il vous a déjà lancé son invitation.\nEmbrasser, engloutir, envelopper, envahir... \nRépondez à l'Appel venu des profondeurs de l'océan, rejoignez cette Chasse sans fin, votre passé, votre moi, tout cela n'a plus aucune importance."
